{
  "name": "bt_llm_send_config_msgs",
  "confidence": "medium",
  "docstring": "Assembles and sends a Bluetooth link-layer configuration message sequence for a selected context, including reset cleanup, advertising-status, RSSI, and rate/power table messages, then dispatches an HCI command.",
  "subsystem": "bt",
  "var_renames": {
    "v0": "config_table_base",
    "v1": "state_ptr",
    "v24": "ctx_idx",
    "v13": "ctx_ptr",
    "v16": "rate_word_ptr",
    "v14": "rate_word_idx",
    "v10": "adv_status",
    "v23": "rssi_msg"
  },
  "struct_hints": [
    {
      "offset": 61,
      "meaning": "context index stored in the state object"
    },
    {
      "offset": 248,
      "meaning": "RSSI status input within the context record"
    },
    {
      "offset": 368,
      "meaning": "32-bit context parameter copied into the message at v3 offset 0"
    },
    {
      "offset": 372,
      "meaning": "16-bit context parameter copied into the message at v3 offset 4"
    },
    {
      "offset": 412,
      "meaning": "byte flag copied to v5 offset 5 and used to skip interval selection when set"
    },
    {
      "offset": 422,
      "meaning": "16-bit context parameter copied into the message at v6 offset 0"
    },
    {
      "offset": 424,
      "meaning": "start of advertising payload passed to llm_decrypt_adv_payload"
    },
    {
      "offset": 440,
      "meaning": "first of four 32-bit rate/power or configuration words"
    },
    {
      "offset": 472,
      "meaning": "context flags; bit 3 enables an RSSI status message"
    }
  ]
}
